/* ============================================================================
   Módulo: SOLICITUD DE ORDEN DE PEDIDO  (agrega a la BD RegistroCodigos)
   Motor: Azure SQL Database (T-SQL)
   Ejecutar DESPUÉS de RegistroCodigos.sql (reutiliza el esquema 'cat').
   ============================================================================ */
SET NOCOUNT ON;
GO
IF SCHEMA_ID('cat') IS NULL EXEC('CREATE SCHEMA cat');
GO

/* Limpieza para re-ejecución */
IF OBJECT_ID('dbo.vOrdenPedido','V') IS NOT NULL DROP VIEW dbo.vOrdenPedido;
IF OBJECT_ID('dbo.OrdenPedido','U')  IS NOT NULL DROP TABLE dbo.OrdenPedido;
IF OBJECT_ID('cat.OP_Producto','U')  IS NOT NULL DROP TABLE cat.OP_Producto;
IF OBJECT_ID('cat.OP_Bodega','U')    IS NOT NULL DROP TABLE cat.OP_Bodega;
IF OBJECT_ID('cat.OP_Proveedor','U') IS NOT NULL DROP TABLE cat.OP_Proveedor;
IF OBJECT_ID('cat.OP_Transporte','U')IS NOT NULL DROP TABLE cat.OP_Transporte;
IF OBJECT_ID('cat.OP_Sector','U')    IS NOT NULL DROP TABLE cat.OP_Sector;
GO

/* Catálogos del módulo (listas desplegables gestionables) */
CREATE TABLE cat.OP_Producto  (Id INT IDENTITY(1,1) PRIMARY KEY, Nombre NVARCHAR(400) NOT NULL UNIQUE, Activo BIT NOT NULL DEFAULT 1);
CREATE TABLE cat.OP_Bodega    (Id INT IDENTITY(1,1) PRIMARY KEY, Nombre NVARCHAR(120) NOT NULL UNIQUE, Activo BIT NOT NULL DEFAULT 1);
CREATE TABLE cat.OP_Proveedor (Id INT IDENTITY(1,1) PRIMARY KEY, Nombre NVARCHAR(200) NOT NULL UNIQUE, Activo BIT NOT NULL DEFAULT 1);
CREATE TABLE cat.OP_Transporte(Id INT IDENTITY(1,1) PRIMARY KEY, Nombre NVARCHAR(60)  NOT NULL UNIQUE, Activo BIT NOT NULL DEFAULT 1);
CREATE TABLE cat.OP_Sector    (Id INT IDENTITY(1,1) PRIMARY KEY, Nombre NVARCHAR(30)  NOT NULL UNIQUE, Activo BIT NOT NULL DEFAULT 1);
GO

/* Tabla principal de órdenes */
CREATE TABLE dbo.OrdenPedido (
    Id                  INT IDENTITY(1,1) PRIMARY KEY,
    ProductoId          INT NOT NULL,
    Descripcion         NVARCHAR(400) NOT NULL,
    Cajas               INT NULL,
    UnidadesPorCaja     INT NULL,
    TotalUnidades       INT NULL,
    BodegaId            INT NULL,
    ProveedorId         INT NOT NULL,
    TransporteId        INT NULL,
    SectorId            INT NULL,
    FechaEntrega        DATE NULL,
    PrecioEspecial      DECIMAL(18,2) NULL,
    NumeroEMB           NVARCHAR(100) NULL,
    FechaVencimientoEMB DATE NULL,
    Observaciones       NVARCHAR(MAX) NULL,
    CreadoPor           NVARCHAR(200) NULL,
    FechaCreacion       DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
    ModificadoPor       NVARCHAR(200) NULL,
    FechaModificacion   DATETIME2(0) NULL,
    CONSTRAINT FK_OP_Producto   FOREIGN KEY (ProductoId)   REFERENCES cat.OP_Producto(Id),
    CONSTRAINT FK_OP_Bodega     FOREIGN KEY (BodegaId)     REFERENCES cat.OP_Bodega(Id),
    CONSTRAINT FK_OP_Proveedor  FOREIGN KEY (ProveedorId)  REFERENCES cat.OP_Proveedor(Id),
    CONSTRAINT FK_OP_Transporte FOREIGN KEY (TransporteId) REFERENCES cat.OP_Transporte(Id),
    CONSTRAINT FK_OP_Sector     FOREIGN KEY (SectorId)     REFERENCES cat.OP_Sector(Id)
);
GO
CREATE INDEX IX_OrdenPedido_Producto ON dbo.OrdenPedido(ProductoId);
GO

/* Vista aplanada para el listado principal */
CREATE VIEW dbo.vOrdenPedido AS
SELECT o.Id, p.Nombre AS Producto, o.Descripcion, o.Cajas, o.TotalUnidades,
       b.Nombre AS Bodega, pr.Nombre AS Proveedor, o.FechaEntrega, o.FechaCreacion, o.CreadoPor
FROM dbo.OrdenPedido o
JOIN cat.OP_Producto  p  ON p.Id = o.ProductoId
LEFT JOIN cat.OP_Bodega    b  ON b.Id = o.BodegaId
JOIN cat.OP_Proveedor pr ON pr.Id = o.ProveedorId;
GO

